1	import { DELIMITER, dirname, resolve } from '@std/path';
2	import {
3	  explicitServicePort,
4	  parseReadmeQuickstartCommands,
5	  README_QUICKSTART_EXPECTED_COMMANDS,
6	  readmeQuickstartArgv,
7	  substituteReadmeQuickstartCommand,
8	} from '../../../domain/readme-quickstart.ts';
9	import { resolveResourceUrlsFromAppHost } from '../scaffold/generated-app-endpoint.ts';
10	import { type AspireCommandRunner, runAspireCommand } from './aspire-walk.ts';
11	
12	const JSR_CLI_PREFIX = 'jsr:@netscript/cli@';
13	const SERVICE_RESOURCE = 'users';
14	const SERVICE_READINESS_PREFIX = `aspire wait ${SERVICE_RESOURCE} `;
15	const RECEIPT_TAIL_LENGTH = 4_000;
16	const DENO_INSTALL_DIRECTORY = '.deno-install';
17	
18	type ServiceUrlResolver = (appHost: string, resourceName: string) => Promise<string[]>;
19	
20	interface ReadmeWalkState {
21	  readonly cwd: string;
22	  readonly denoInstallRoot: string;
23	  readonly nextIndex: number;
24	  readonly servicePort?: number;
25	  readonly servicePortSource?: string;
26	  readonly servicePortError?: string;
27	}
28	
29	interface ReadmeCommandReceipt {
30	  readonly argv: readonly string[];
31	  readonly cwd: string;
32	  readonly durationMs: number;
33	  readonly environment: {
34	    readonly denoInstallRoot: string;
35	    readonly pathPrepend: string;
36	  };
37	  readonly exitCode: number;
38	  readonly readmeLine: number;
39	  readonly sourceCommand: string;
40	  readonly stderrTail: string;
41	  readonly stdoutTail: string;
42	  readonly substitutions: {
43	    readonly port?: number;
44	    readonly version?: string;
45	  };
46	  readonly evidence?: {
47	    readonly error?: string;
48	    readonly servicePort?: number;
49	    readonly source?: string;
50	  };
51	  readonly timedOut: boolean;
52	  readonly failureDiagnostics?: {
53	    readonly argv: readonly string[];
54	    readonly exitCode: number;
55	    readonly stdoutTail: string;
56	    readonly stderrTail: string;
57	    readonly timedOut: boolean;
58	  };
59	}
60	
61	/** Execute one indexed root README Quickstart command and emit its child receipt. */
62	export async function executeReadmeQuickstartCommand(
63	  repoRoot: string,
64	  runRoot: string,
65	  appHost: string,
66	  index: number,
67	  cliSpecifier: string,
68	  statePath: string,
69	  timeoutMs: number,
70	  spawn: AspireCommandRunner = runAspireCommand,
71	  resolveServiceUrls: ServiceUrlResolver = resolveResourceUrlsFromAppHost,
72	): Promise<number> {
73	  const readme = await Deno.readTextFile(resolve(repoRoot, 'README.md'));
74	  const commands = parseReadmeQuickstartCommands(readme);
75	  assertExpectedCommands(commands.map((entry) => entry.command));
76	  const entry = commands[index];
77	  if (!entry) throw new Error(`README Quickstart command index ${index} does not exist.`);
78	
79	  const version = publishedVersion(cliSpecifier, entry.line);
80	  const state = index === 0
81	    ? await initializeState(runRoot, statePath)
82	    : await readState(statePath, entry.line);
83	  if (state.nextIndex !== index) {
84	    throw new Error(
85	      `README line ${entry.line} cannot run out of order: expected command index ` +
86	        `${state.nextIndex}, received ${index}.`,
87	    );
88	  }
89	
90	  if (
91	    entry.command.includes('<port>') && state.servicePort === undefined && state.servicePortError
92	  ) {
93	    throw new Error(
94	      `README line ${entry.line} cannot substitute <port>: ${state.servicePortError}.`,
95	    );
96	  }
97	  const substituted = substituteReadmeQuickstartCommand(
98	    entry.command,
99	    { version, port: state.servicePort },
100	    entry.line,
101	  );
102	  const argv = readmeQuickstartArgv(substituted, entry.line);
103	  const environment = readmeCommandEnvironment(state.denoInstallRoot);
104	  const started = performance.now();
105	  const result = argv[0] === 'cd'
106	    ? await changeDirectory(argv, state.cwd, entry.line)
107	    : await runCommand(argv, state.cwd, timeoutMs, environment.env, spawn);
108	  const durationMs = Math.round(performance.now() - started);
109	  let nextState: ReadmeWalkState = state;
110	  if (result.code === 0 && !result.timedOut) {
111	    nextState = {
112	      ...state,
113	      cwd: argv[0] === 'cd' ? resolve(state.cwd, argv[1]) : state.cwd,
114	      nextIndex: index + 1,
115	    };
116	    if (entry.command.startsWith(SERVICE_READINESS_PREFIX)) {
117	      nextState = await captureServicePort(nextState, appHost, resolveServiceUrls);
118	    }
119	    await writeState(statePath, nextState);
120	  }
121	
122	  // Observe the failing resource before owned cleanup removes its console evidence.
123	  // This read-only probe fits within the wrapper grace and never changes the command verdict.
124	  let failureDiagnostics: ReadmeCommandReceipt['failureDiagnostics'];
125	  if (
126	    entry.command.startsWith(SERVICE_READINESS_PREFIX) && (result.code !== 0 || result.timedOut)
127	  ) {
128	    const logArgv = [
129	      'aspire',
130	      'logs',
131	      SERVICE_RESOURCE,
132	      '--tail',
133	      '40',
134	      '--format',
135	      'Json',
136	      '--apphost',
137	      appHost,
138	    ];
139	    const logs = await runCommand(logArgv, state.cwd, 2_000, environment.env, spawn);
140	    failureDiagnostics = {
141	      argv: logArgv,
142	      exitCode: logs.code,
143	      stdoutTail: tail(logs.stdout),
144	      stderrTail: tail(logs.stderr),
145	      timedOut: logs.timedOut,
146	    };
147	  }
148	  const receipt: ReadmeCommandReceipt = Object.freeze({
149	    argv,
150	    cwd: state.cwd,
151	    durationMs,
152	    environment: Object.freeze({
153	      denoInstallRoot: state.denoInstallRoot,
154	      pathPrepend: environment.pathPrepend,
155	    }),
156	    exitCode: result.code,
157	    readmeLine: entry.line,
158	    sourceCommand: entry.command,
159	    stderrTail: tail(result.stderr),
160	    stdoutTail: tail(result.stdout),
161	    substitutions: Object.freeze({
162	      ...(entry.command.includes('<version>') ? { version } : {}),
163	      ...(entry.command.includes('<port>') && state.servicePort !== undefined
164	        ? { port: state.servicePort }
165	        : {}),
166	    }),
167	    ...(entry.command.startsWith(SERVICE_READINESS_PREFIX) &&
168	        (nextState.servicePort !== undefined || nextState.servicePortError !== undefined)
169	      ? {
170	        evidence: {
171	          ...(nextState.servicePort === undefined ? {} : { servicePort: nextState.servicePort }),
172	          ...(nextState.servicePortSource === undefined
173	            ? {}
174	            : { source: nextState.servicePortSource }),
175	          ...(nextState.servicePortError === undefined
176	            ? {}
177	            : { error: nextState.servicePortError }),
178	        },
179	      }
180	      : {}),
181	    timedOut: result.timedOut,
182	    ...(failureDiagnostics === undefined ? {} : { failureDiagnostics }),
183	  });
184	  await writeReceipt(statePath, index, receipt);
185	  console.info(JSON.stringify(receipt));
186	  if (result.code !== 0 || result.timedOut) {
187	    console.error(
188	      `README line ${entry.line} failed exactly as printed: ${entry.command}`,
189	    );
190	  }
191	  return result.code;
192	}
193	
194	async function runCommand(
195	  argv: readonly string[],
196	  cwd: string,
197	  timeoutMs: number,
198	  env: Record<string, string>,
199	  spawn: AspireCommandRunner,
200	): Promise<{ code: number; stdout: string; stderr: string; timedOut: boolean }> {
201	  try {
202	    return await spawn(argv, cwd, timeoutMs, env);
203	  } catch (error) {
204	    return {
205	      code: 1,
206	      stdout: '',
207	      stderr: `Command could not start: ${errorMessage(error)}`,
208	      timedOut: false,
209	    };
210	  }
211	}
212	
213	async function initializeState(runRoot: string, statePath: string): Promise<ReadmeWalkState> {
214	  await Deno.mkdir(runRoot, { recursive: true });
215	  const denoInstallRoot = resolve(runRoot, DENO_INSTALL_DIRECTORY);
216	  try {
217	    await Deno.remove(denoInstallRoot, { recursive: true });
218	  } catch (error) {
219	    if (!(error instanceof Deno.errors.NotFound)) throw error;
220	  }
221	  await Deno.mkdir(denoInstallRoot, { recursive: true });
222	  try {
223	    await Deno.remove(resolve(dirname(statePath), 'receipts'), { recursive: true });
224	  } catch (error) {
225	    if (!(error instanceof Deno.errors.NotFound)) throw error;
226	  }
227	  return Object.freeze({ cwd: runRoot, denoInstallRoot, nextIndex: 0 });
228	}
229	
230	function readmeCommandEnvironment(
231	  denoInstallRoot: string,
232	): { env: Record<string, string>; pathPrepend: string } {
233	  const pathPrepend = resolve(denoInstallRoot, 'bin');
234	  return {
235	    env: {
236	      DENO_INSTALL_ROOT: denoInstallRoot,
237	      PATH: `${pathPrepend}${DELIMITER}${Deno.env.get('PATH') ?? ''}`,
238	    },
239	    pathPrepend,
240	  };
241	}
242	
243	function assertExpectedCommands(actual: readonly string[]): void {
244	  if (actual.length !== README_QUICKSTART_EXPECTED_COMMANDS.length) {
245	    throw new Error(
246	      `README Quickstart contains ${actual.length} commands; ` +
247	        `readme.quickstart expects ${README_QUICKSTART_EXPECTED_COMMANDS.length}.`,
248	    );
249	  }
250	  for (let index = 0; index < actual.length; index++) {
251	    if (actual[index] !== README_QUICKSTART_EXPECTED_COMMANDS[index]) {
252	      throw new Error(
253	        `README Quickstart command ${index + 1} diverged: expected ` +
254	          `${JSON.stringify(README_QUICKSTART_EXPECTED_COMMANDS[index])}, received ` +
255	          `${JSON.stringify(actual[index])}.`,
256	      );
257	    }
258	  }
259	}
260	
261	function publishedVersion(specifier: string, line: number): string {
262	  if (!specifier.startsWith(JSR_CLI_PREFIX)) {
263	    throw new Error(
264	      `README line ${line} requires --source jsr and --cli ${JSR_CLI_PREFIX}<version>.`,
265	    );
266	  }
267	  const version = specifier.slice(JSR_CLI_PREFIX.length);
268	  if (!version || /\s/.test(version)) {
269	    throw new Error(`README line ${line} received an invalid published CLI version.`);
270	  }
271	  return version;
272	}
273	
274	async function changeDirectory(
275	  argv: readonly string[],
276	  cwd: string,
277	  line: number,
278	): Promise<{ code: number; stdout: string; stderr: string; timedOut: boolean }> {
279	  if (argv.length !== 2) {
280	    return {
281	      code: 2,
282	      stdout: '',
283	      stderr: `README line ${line} has an unsupported cd shape.`,
284	      timedOut: false,
285	    };
286	  }
287	  const target = resolve(cwd, argv[1]);
288	  try {
289	    const info = await Deno.stat(target);
290	    if (!info.isDirectory) throw new Error('target is not a directory');
291	    return { code: 0, stdout: '', stderr: '', timedOut: false };
292	  } catch (error) {
293	    return {
294	      code: 1,
295	      stdout: '',
296	      stderr: `README line ${line} cd ${argv[1]} failed: ${errorMessage(error)}`,
297	      timedOut: false,
298	    };
299	  }
300	}
301	
302	async function captureServicePort(
303	  state: ReadmeWalkState,
304	  appHost: string,
305	  resolveServiceUrls: ServiceUrlResolver,
306	): Promise<ReadmeWalkState> {
307	  try {
308	    const urls = await resolveServiceUrls(appHost, SERVICE_RESOURCE);
309	    const port = explicitServicePort(urls);
310	    return Object.freeze({
311	      ...state,
312	      servicePort: port,
313	      servicePortSource: `aspire describe ${SERVICE_RESOURCE} run receipt`,
314	    });
315	  } catch (error) {
316	    return Object.freeze({
317	      ...state,
318	      servicePortError: `service-port receipt failed: ${errorMessage(error)}`,
319	    });
320	  }
321	}
322	
323	async function readState(path: string, line: number): Promise<ReadmeWalkState> {
324	  let parsed: unknown;
325	  try {
326	    parsed = JSON.parse(await Deno.readTextFile(path));
327	  } catch (error) {
328	    throw new Error(`README line ${line} cannot read prior run receipt: ${errorMessage(error)}.`);
329	  }
330	  if (
331	    !isRecord(parsed) || typeof parsed.cwd !== 'string' ||
